  <body>
    <div class="container">
      <div class="header">
        <h1>Claude Code Trace Visualizer</h1>
        <p style="color: var(--text-secondary)">
          Visualize Claude AI conversation traces with tool calls and thinking
          blocks
        </p>
      </div>

      <div class="upload-section">
        <div class="upload-area" id="uploadArea">
          <p>
            Drop a conversation JSON file here or click to upload (or it
            automatically loads conversation.json)
          </p>
          <input type="file" id="fileInput" accept=".json" />
        </div>
      </div>

      <div id="content"></div>
    </div>

    <script>
      const uploadArea = document.getElementById("uploadArea");
      const fileInput = document.getElementById("fileInput");
      const content = document.getElementById("content");

      // Drag and drop handlers
      uploadArea.addEventListener("dragover", (e) => {
        e.preventDefault();
        uploadArea.classList.add("dragover");
      });

      uploadArea.addEventListener("dragleave", () => {
        uploadArea.classList.remove("dragover");
      });

      uploadArea.addEventListener("drop", (e) => {
        e.preventDefault();
        uploadArea.classList.remove("dragover");
        const file = e.dataTransfer.files[0];
        if (file) processFile(file);
      });

      uploadArea.addEventListener("click", () => fileInput.click());

      fileInput.addEventListener("change", (e) => {
        const file = e.target.files[0];
        if (file) processFile(file);
      });

      function processFile(file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          try {
            const data = JSON.parse(e.target.result);
            renderConversation(data);
          } catch (err) {
            content.innerHTML = `<div class="error-message">Error parsing JSON: ${err.message}</div>`;
          }
        };
        reader.readAsText(file);
      }

      function renderConversation(data) {
        // Handle both array format and object with messages property
        const messages = Array.isArray(data) ? data : data.messages || [];

        if (messages.length === 0) {
          content.innerHTML =
            '<div class="error-message">No messages found in the conversation data.</div>';
          return;
        }

        // Calculate stats
        const stats = calculateStats(messages);

        let html = `
                <div class="stats-bar">
                    <div class="stat-item">
                        <span>Messages:</span>
                        <span class="stat-value">${stats.totalMessages}</span>
                    </div>
                    <div class="stat-item">
                        <span>Tool Calls:</span>
                        <span class="stat-value">${stats.toolCalls}</span>
                    </div>
                    <div class="stat-item">
                        <span>Thinking Blocks:</span>
                        <span class="stat-value">${stats.thinkingBlocks}</span>
                    </div>
                </div>
                <div class="controls">
                    <button class="btn" onclick="expandAll()">Expand All</button>
                    <button class="btn" onclick="collapseAll()">Collapse All</button>
                </div>
                <div class="conversation-flow">
            `;

        messages.forEach((message, index) => {
          html += renderMessage(message, index);
        });

        html += "</div>";
        content.innerHTML = html;
      }

      function calculateStats(messages) {
        let toolCalls = 0;
        let thinkingBlocks = 0;

        messages.forEach((msg) => {
          if (Array.isArray(msg.content)) {
            msg.content.forEach((block) => {
              if (block.type === "tool_use") toolCalls++;
              if (block.type === "thinking") thinkingBlocks++;
            });
          }
        });

        return {
          totalMessages: messages.length,
          toolCalls,
          thinkingBlocks,
        };
      }

      function renderMessage(message, index) {
        const role = message.role || "unknown";
        const roleClass = `role-${role}`;

        // Get preview text
        const preview = getMessagePreview(message);

        let html = `
                <div class="message" data-index="${index}">
                    <div class="message-header" onclick="toggleMessage(${index})">
                        <span class="role-badge ${roleClass}">${role}</span>
                        <span class="message-preview">${escapeHtml(preview)}</span>
                        <span class="toggle-icon">▼</span>
                    </div>
                    <div class="message-content">
            `;

        html += renderMessageContent(message);

        html += `
                    </div>
                </div>
            `;

        return html;
      }

      function getMessagePreview(message) {
        if (typeof message.content === "string") {
          return message.content.substring(0, 100);
        }

        if (Array.isArray(message.content)) {
          for (const block of message.content) {
            if (block.type === "text" && block.text) {
              return block.text.substring(0, 100);
            }
            if (block.type === "tool_use") {
              return `Tool: ${block.name}`;
            }
            if (block.type === "tool_result") {
              return `Tool Result: ${block.tool_use_id}`;
            }
          }
        }

        return "...";
      }

      function renderMessageContent(message) {
        // Check if this is a tool_result with an agent pattern
        if (message.role === "user" && Array.isArray(message.content)) {
          // Look for tool_result blocks that might contain agent content
          const toolResults = message.content.filter(
            (block) => block.type === "tool_result"
          );

          let html = "";
          for (const block of message.content) {
            if (block.type === "tool_result") {
              const agentContent = tryParseAgentContent(block.content);
              if (agentContent) {
                html += renderAgentContainer(agentContent, block.tool_use_id);
              } else {
                html += renderContentBlock(block);
              }
            } else {
              html += renderContentBlock(block);
            }
          }
          return html;
        }

        if (typeof message.content === "string") {
          return `<div class="content-block text">
                        <div class="block-content text-content">${formatText(message.content)}</div>
                    </div>`;
        }

        if (Array.isArray(message.content)) {
          return message.content.map(renderContentBlock).join("");
        }

        return `<div class="content-block">
                    <div class="block-content"><pre>${escapeHtml(JSON.stringify(message.content, null, 2))}</pre></div>
                </div>`;
      }

      function tryParseAgentContent(content) {
        // Agent content is typically a string that might contain structured data
        // or follow a pattern indicating agent tool usage
        if (typeof content !== "string") return null;

        // Look for patterns that indicate this is an agent's work
        // Check if it looks like a sequence of tool calls and results

        // Pattern 1: Content that contains tool call/result markers
        const hasToolPattern =
          content.includes("Tool:") ||
          content.includes("tool_use") ||
          content.includes("Result:");

        // Pattern 2: Content that looks like it came from a sub-agent
        const looksLikeAgentOutput =
          content.length > 500 && // Substantial content
          (content.includes("```") || // Contains code blocks
            content.includes("I ") || // First person (agent speaking)
            /^(Here|The|This|I've|Based)/m.test(content)); // Common agent opening phrases

        if (!hasToolPattern && !looksLikeAgentOutput) return null;

        return {
          type: "agent",
          rawContent: content,
        };
      }

      function renderAgentContainer(agentContent, toolUseId) {
        const preview = agentContent.rawContent.substring(0, 100) + "...";
        const containerId = `agent-${toolUseId}`;

        return `
                <div class="agent-container" id="${containerId}">
                    <div class="agent-header" onclick="toggleAgent('${containerId}')">
                        <span class="agent-badge">Agent</span>
                        <span class="agent-name">Sub-agent Execution</span>
                        <span class="agent-toggle-icon">▼</span>
                    </div>
                    <div class="agent-content">
                        <div class="agent-turns">
                            <div class="agent-turn">
                                <div class="agent-turn-content">
                                    ${formatText(agentContent.rawContent)}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            `;
      }

      function toggleAgent(containerId) {
        const container = document.getElementById(containerId);
        if (container) {
          container.classList.toggle("expanded");
        }
      }

      function renderContentBlock(block) {
        switch (block.type) {
          case "text":
            return `
                        <div class="content-block text">
                            <div class="block-header">
                                <span>📝 Text</span>
                            </div>
                            <div class="block-content text-content">${formatText(block.text)}</div>
                        </div>
                    `;

          case "thinking":
            const thinkingId = `thinking-${Math.random().toString(36).substr(2, 9)}`;
            const thinkingPreview = (block.thinking || "").substring(0, 150);
            return `
                        <div class="content-block thinking">
                            <div class="block-header">
                                <span>🧠 Thinking</span>
                            </div>
                            <div class="block-content">
                                <div class="collapsible-section">
                                    <div class="summary-text">${escapeHtml(thinkingPreview)}${block.thinking && block.thinking.length > 150 ? "..." : ""}</div>
                                    <div class="collapsible-header" onclick="toggleCollapsible('${thinkingId}')">
                                        <span>▶</span>
                                        <span>Show full thinking</span>
                                    </div>
                                    <div class="collapsible-content" id="${thinkingId}">
                                        <div class="thinking-content">${formatText(block.thinking || "")}</div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;

          case "tool_use":
            return `
                        <div class="content-block tool-use">
                            <div class="block-header">
                                <span>🔧 Tool Use</span>
                            </div>
                            <div class="block-content">
                                <div><span class="tool-name">${escapeHtml(block.name)}</span></div>
                                <div class="tool-input">
                                    <pre>${formatJson(block.input)}</pre>
                                </div>
                            </div>
                        </div>
                    `;

          case "tool_result":
            return `
                        <div class="content-block tool-result">
                            <div class="block-header">
                                <span>✅ Tool Result</span>
                            </div>
                            <div class="block-content">
                                ${formatToolResult(block.content)}
                            </div>
                        </div>
                    `;

          default:
            return `
                        <div class="content-block">
                            <div class="block-header">
                                <span>📦 ${escapeHtml(block.type || "Unknown")}</span>
                            </div>
                            <div class="block-content">
                                <pre>${escapeHtml(JSON.stringify(block, null, 2))}</pre>
                            </div>
                        </div>
                    `;
        }
      }

      function formatToolResult(content) {
        if (typeof content === "string") {
          // Check if it looks like JSON
          try {
            const parsed = JSON.parse(content);
            return `<pre>${formatJson(parsed)}</pre>`;
          } catch {
            // Check if it's very long content
            if (content.length > 500) {
              const previewId = `preview-${Math.random().toString(36).substr(2, 9)}`;
              return `
                            <div class="collapsible-section">
                                <div class="summary-text">${escapeHtml(content.substring(0, 200))}...</div>
                                <div class="collapsible-header" onclick="toggleCollapsible('${previewId}')">
                                    <span>▶</span>
                                    <span>Show full result (${content.length} chars)</span>
                                </div>
                                <div class="collapsible-content" id="${previewId}">
                                    <pre>${escapeHtml(content)}</pre>
                                </div>
                            </div>
                        `;
            }
            return `<pre>${escapeHtml(content)}</pre>`;
          }
        }

        if (Array.isArray(content)) {
          return content
            .map((item) => {
              if (item.type === "text") {
                return `<pre>${escapeHtml(item.text)}</pre>`;
              }
              return `<pre>${escapeHtml(JSON.stringify(item, null, 2))}</pre>`;
            })
            .join("");
        }

        return `<pre>${escapeHtml(JSON.stringify(content, null, 2))}</pre>`;
      }

      function formatJson(obj) {
        const json = JSON.stringify(obj, null, 2);
        return escapeHtml(json)
          .replace(
            /"([^"]+)":/g,
            '<span class="json-key">"$1"</span>:'
          )
          .replace(
            /: "([^"]*)"/g,
            ': <span class="json-string">"$1"</span>'
          )
          .replace(
            /: (\d+)/g,
            ': <span class="json-number">$1</span>'
          )
          .replace(
            /: (true|false)/g,
            ': <span class="json-boolean">$1</span>'
          );
      }

      function formatText(text) {
        if (!text) return "";

        // Basic markdown-like formatting
        let formatted = escapeHtml(text);

        // Convert code blocks
        formatted = formatted.replace(
          /```(\w*)\n([\s\S]*?)```/g,
          '<pre><code class="language-$1">$2</code></pre>'
        );

        // Convert inline code
        formatted = formatted.replace(
          /`([^`]+)`/g,
          '<code>$1</code>'
        );

        // Convert bold
        formatted = formatted.replace(
          /\*\*([^*]+)\*\*/g,
          "<strong>$1</strong>"
        );

        // Convert italic
        formatted = formatted.replace(
          /\*([^*]+)\*/g,
          "<em>$1</em>"
        );

        // Convert line breaks
        formatted = formatted.replace(/\n/g, "<br>");

        return formatted;
      }

      function escapeHtml(text) {
        if (typeof text !== "string") return String(text);
        const div = document.createElement("div");
        div.textContent = text;
        return div.innerHTML;
      }

      function toggleMessage(index) {
        const message = document.querySelector(
          `.message[data-index="${index}"]`
        );
        if (message) {
          message.classList.toggle("expanded");
        }
      }

      function toggleCollapsible(id) {
        const element = document.getElementById(id);
        if (element) {
          element.classList.toggle("expanded");
          const header = element.previousElementSibling;
          if (header) {
            const arrow = header.querySelector("span");
            if (arrow) {
              arrow.textContent = element.classList.contains("expanded")
                ? "▼"
                : "▶";
            }
          }
        }
      }

      function expandAll() {
        document
          .querySelectorAll(".message")
          .forEach((m) => m.classList.add("expanded"));
      }

      function collapseAll() {
        document
          .querySelectorAll(".message")
          .forEach((m) => m.classList.remove("expanded"));
      }

      // Auto-load conversation.json if it exists
      fetch("conversation.json")
        .then((response) => {
          if (response.ok) return response.json();
          throw new Error("No default file");
        })
        .then((data) => renderConversation(data))
        .catch(() => {
          // No default file, wait for upload
        });
    </script>
